  `min_order_amount` decimal(12,2) DEFAULT NULL COMMENT 'Мин. сумма заказа',
  `max_discount_amount` decimal(12,2) DEFAULT NULL COMMENT 'Макс. размер скидки',
  `starts_at` datetime DEFAULT NULL COMMENT 'Начало действия',
  `ends_at` datetime DEFAULT NULL COMMENT 'Окончание действия',
  `schedule_days` json DEFAULT NULL COMMENT '[0,1,2,3,4,5,6] дни недели',
  `schedule_time_start` time DEFAULT NULL COMMENT 'Время начала в течение дня',
  `schedule_time_end` time DEFAULT NULL COMMENT 'Время окончания в течение дня',
  `usage_limit` int UNSIGNED DEFAULT NULL COMMENT 'Общий лимит использований',
  `usage_per_customer` int UNSIGNED DEFAULT NULL COMMENT 'Лимит на клиента',
  `usage_count` int UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Текущее кол-во использований',
  `priority` int NOT NULL DEFAULT '0' COMMENT 'Приоритет (выше = важнее)',
  `is_stackable` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Можно совмещать',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `activation_mode` enum('auto','promo_code') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'auto',
  `reward_type` enum('discount','bonus','gift','product_discount','mixed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'discount',
  `promo_code_mode` enum('shared','unique') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unique_code_usage_limit` int UNSIGNED DEFAULT NULL,
  `mechanic_type` enum('simple_discount','buy_x_get_y','threshold') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'simple_discount',
